body.script:
//
function fillApplicant(val) {
    var manualWrap = document.getElementById('manual-name-wrap');
    if(val === '__manual__') {
        manualWrap.style.display = 'block';
        document.getElementById('inp_first').value = '';
        document.getElementById('inp_last').value = '';
        document.getElementById('inp_email').value = '';
        document.getElementById('inp_mobile').value = '';
        return;
    }
    manualWrap.style.display = 'none';
    var sel = document.getElementById('applicant_sel');
    var opt = sel.options[sel.selectedIndex];
    if(opt) {
        document.getElementById('inp_first').value = opt.getAttribute('data-first') || '';
        document.getElementById('inp_last').value = opt.getAttribute('data-last') || '';
        document.getElementById('inp_email').value = opt.getAttribute('data-email') || '';
        document.getElementById('inp_mobile').value = opt.getAttribute('data-mobile') || '';
    }
}
function updateFlag(code) {
    var sel = document.getElementById('phone_code_sel');
    var opt = sel.options[sel.selectedIndex];
    var flag = opt ? opt.getAttribute('data-flag') : '&#127462;&#127466;';
    document.getElementById('phone-flag').innerHTML = flag || '&#127462;&#127466;';
}
function checkReason(v) { checkExtraFields(); }
function checkMonths(v) { checkExtraFields(); }
function checkExtraFields() {
    var m = document.getElementById('months_sel').value;
    document.getElementById('extra-fields').style.display = m ? 'block' : 'none';
}

function reentryValidateStep1() {
  var valid = true;
  function showErr(id, msg) { var el=document.getElementById(id); if(el){el.textContent=msg;el.style.display='block';} }
  function hideErr(id) { var el=document.getElementById(id); if(el) el.style.display='none'; }

  // Applicant name
  var apSel = document.getElementById('applicant_sel');
  var manName = document.getElementById('manual_full_name');
  if (apSel && apSel.value === '__manual__') {
    var mv = manName ? manName.value.trim() : '';
    if (mv.length < 3 || mv.length > 50) { showErr('ap_name_err','Please enter applicant name (3-50 characters).'); valid=false; } else hideErr('ap_name_err');
  } else {
    if (!apSel || !apSel.value) { showErr('ap_name_err','Please select or enter applicant name.'); valid=false; } else hideErr('ap_name_err');
  }

  var fn = document.querySelector('[name="first_name"]');
  var fnv = fn ? fn.value.trim() : '';
  if (fnv.length < 3 || fnv.length > 50) { showErr('fname_err','First name must be 3-50 characters.'); valid=false; } else hideErr('fname_err');

  var ln = document.querySelector('[name="last_name"]');
  var lnv = ln ? ln.value.trim() : '';
  if (lnv.length < 3 || lnv.length > 50) { showErr('lname_err','Last name must be 3-50 characters.'); valid=false; } else hideErr('lname_err');

  var mob = document.querySelector('[name="mobile"]');
  var mobv = mob ? mob.value.trim().replace(/\D/g,'') : '';
  if (mobv.length < 10 || mobv.length > 15) { showErr('mobile_err','Mobile number must be 10-15 digits.'); valid=false; } else hideErr('mobile_err');

  var em = document.querySelector('[name="email"]');
  var emv = em ? em.value.trim() : '';
  if (!emv || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(emv)) { showErr('email_err','Please enter a valid email address.'); valid=false; } else hideErr('email_err');

  var pp = document.querySelector('[name="passport_number"]');
  var ppv = pp ? pp.value.trim() : '';
  if (!ppv || ppv.length < 6 || ppv.length > 20 || !/^[A-Za-z0-9]+$/.test(ppv)) { showErr('re_pass_err','Passport number must be 6-20 alphanumeric characters.'); valid=false; } else hideErr('re_pass_err');

  var desig = document.querySelector('[name="designation"]');
  if (!desig || !desig.value) { showErr('desig_err','Please select designation.'); valid=false; } else hideErr('desig_err');

  var reason = document.querySelector('[name="reason_outside_uae"]');
  if (!reason || !reason.value) { showErr('reason_err','Please select reason for staying outside Dubai.'); valid=false; } else hideErr('reason_err');

  var months = document.querySelector('[name="months_outside_uae"]');
  if (!months || !months.value) { showErr('months_err','Please select number of months outside Dubai.'); valid=false; } else hideErr('months_err');

  var docs = [
    ['doc_passport','doc_pass_err','Passport copy is required.'],
    ['doc_visa','doc_visa_err','Residential copy is required.'],
  ];
  docs.forEach(function(d) {
    var el = document.querySelector('[name="'+d[0]+'"]');
    if (!el || !el.files || el.files.length === 0) { showErr(d[1], d[2]); valid=false; } else hideErr(d[1]);
  });

  var vid = document.querySelector('[name="visa_issue_date"]');
  if (!vid || !vid.value) { showErr('issue_date_err','Please select visa issue date.'); valid=false; } else hideErr('issue_date_err');

  var ved = document.querySelector('[name="visa_expiry_date"]');
  if (!ved || !ved.value) { showErr('expiry_date_err','Please select visa expiry date.'); valid=false; } else hideErr('expiry_date_err');

  if (valid) document.querySelector('form').submit();
}
//
//

//
function reentryValidateDecl() {
  var valid = true;
  function showErr(id, msg) { var el=document.getElementById(id); if(el){el.textContent=msg;el.style.display='block';} }
  function hideErr(id) { var el=document.getElementById(id); if(el) el.style.display='none'; }
  var decl = document.querySelector('[name="declaration_accepted"]');
  if (!decl || !decl.checked) { showErr('re_decl_err','Please agree to the declaration to proceed.'); valid=false; } else hideErr('re_decl_err');
  if (valid) document.querySelector('form').submit();
}
//
//

//
function toggleAdditional(v) {
    document.getElementById('additional-fields').style.display = v === 'yes' ? 'block' : 'none';
}

function leaseValidateStep1() {
  var valid = true;
  function showErr(id, msg) { var el=document.getElementById(id); if(el){el.textContent=msg;el.style.display='block';} }
  function hideErr(id) { var el=document.getElementById(id); if(el) el.style.display='none'; }

  var cn = document.querySelector('[name="company_name"]');
  var cnv = cn ? cn.value.trim() : '';
  if (cnv.length < 3 || cnv.length > 50) { showErr('cname_err','Company name must be 3-50 characters.'); valid=false; } else hideErr('cname_err');

  var mfn = document.querySelector('[name="manager_first_name"]');
  var mfnv = mfn ? mfn.value.trim() : '';
  if (mfnv.length < 3 || mfnv.length > 50) { showErr('mfname_err','Manager first name must be 3-50 characters.'); valid=false; } else hideErr('mfname_err');

  var mln = document.querySelector('[name="manager_last_name"]');
  var mlnv = mln ? mln.value.trim() : '';
  if (mlnv.length < 3 || mlnv.length > 50) { showErr('mlname_err','Manager last name must be 3-50 characters.'); valid=false; } else hideErr('mlname_err');

  var ara = document.querySelector('[name="full_name_arabic"]');
  var arav = ara ? ara.value.trim() : '';
  if (!arav || !/^[؀-ۿ\s]+$/.test(arav)) { showErr('arabic_err','Please enter full name in Arabic only.'); valid=false; } else hideErr('arabic_err');

  var nat = document.querySelector('[name="nationality_id"]');
  if (!nat || !nat.value) { showErr('nat_err','Please select nationality.'); valid=false; } else hideErr('nat_err');

  var pp = document.querySelector('[name="passport_number"]');
  var ppv = pp ? pp.value.trim() : '';
  if (!ppv || ppv.length < 6 || ppv.length > 20 || !/^[A-Za-z0-9]+$/.test(ppv)) { showErr('pass_err','Passport number must be 6-20 alphanumeric characters.'); valid=false; } else hideErr('pass_err');

  var desc = document.querySelector('[name="description_en"]');
  var descv = desc ? desc.value.trim() : '';
  if (descv.length < 3 || descv.length > 1000) { showErr('desc_err','Description must be 3-1000 characters.'); valid=false; } else hideErr('desc_err');

  var addr = document.querySelector('[name="address_en"]');
  var addrv = addr ? addr.value.trim() : '';
  if (addrv.length < 3 || addrv.length > 1000) { showErr('addr_err','Address must be 3-1000 characters.'); valid=false; } else hideErr('addr_err');

  var lv = document.querySelector('[name="lease_validity"]');
  if (!lv || !lv.value) { showErr('lvalid_err','Please select lease validity.'); valid=false; } else hideErr('lvalid_err');

  var cd = document.querySelector('[name="commencement_date"]');
  if (!cd || !cd.value) { showErr('comm_date_err','Please select commencement date.'); valid=false; } else hideErr('comm_date_err');

  var ed = document.querySelector('[name="lease_expiry_date"]');
  if (!ed || !ed.value) { showErr('expiry_date_err','Please select lease expiry date.'); valid=false; } else hideErr('expiry_date_err');

  if (valid) document.querySelector('form').submit();
}
